state.eventChannelFilters={home:'전체',events:'전체','workspace-detail':'전체'};
function eventChannel(basic){return basic?.channel|| (basic?.type==='온라인 이벤트'?'온라인':'오프라인')}
function eventChannelMatches(basic){const selected=state.eventChannelFilters[route()]||'전체';return selected==='전체'||eventChannel(basic)===selected}
function channelFilterControl(){const selected=state.eventChannelFilters[route()]||'전체';return `<select class="event-channel-filter" data-channel-filter aria-label="온라인·오프라인 행사 필터">${['전체','온라인','오프라인'].map(t=>`<option value="${t}" ${selected===t?'selected':''}>${t==='전체'?'전체 운영 방식':t}</option>`).join('')}</select>`}
function eventPeriod(basic,year=new Date().getFullYear()){if(!basic?.start||!basic?.end)return '';const includeYear=basic.start.slice(0,4)!==String(year)||basic.end.slice(0,4)!==String(year);return [basic.start,basic.end].map(d=>(includeYear?d:d.slice(5)).replaceAll('-','.')).join(' — ')}
state.basic={name:'',start:'',end:'',type:'팝업스토어',place:''};state.eventName='';state.brandFilter='전체';
function brandOptions(all=false){return (all?'<option value="전체">전체 브랜드</option>':'')+brands.map(b=>`<option value="${b.id}" ${(all?state.brandFilter:state.brandId)===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}
function basicInfo(){return shell(`${title('NEW EVENT','새 행사를 시작해볼까요?','기본 정보를 입력한 다음, 게임을 만들고 경품을 설정합니다.')}<form id="basic-form" class="panel basic-panel"><div class="field"><label for="event-name">행사명 <span class="required">*</span></label><input id="event-name" required maxlength="80" placeholder="예: 루미에르 성수 팝업 룰렛" value="${esc(state.basic.name)}" autofocus><p class="mini-label">관리 화면과 브랜드사 공유 화면에 표시됩니다.</p></div><div class="field"><label for="basic-brand">브랜드 <span class="required">*</span></label><select id="basic-brand">${brandOptions()}</select></div><div class="grid cols-2"><div class="field"><label for="event-start">시작일 <span class="required">*</span></label><input id="event-start" type="date" required value="${state.basic.start}"></div><div class="field"><label for="event-end">종료일 <span class="required">*</span></label><input id="event-end" type="date" required value="${state.basic.end}"></div></div><div class="grid cols-2"><div class="field"><label for="event-type">행사 유형</label><select id="event-type">${['팝업스토어','박람회·전시','브랜드 프로모션','온라인 이벤트'].map(t=>`<option ${state.basic.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="event-place">장소 <span class="dim">선택</span></label><input id="event-place" placeholder="예: 성수 팝업스토어" value="${esc(state.basic.place)}"></div></div><div id="basic-error" class="alert" hidden></div><div class="basic-footer"><a href="#home" class="muted-btn">취소</a><button type="submit" class="btn">다음 · 게임 제작 →</button></div></form><p class="basic-note">기본 정보는 게임 편집 화면에서도 다시 확인할 수 있습니다.</p>`)}
function storeBasics(){state.basic={name:document.getElementById('event-name').value.trim(),start:document.getElementById('event-start').value,end:document.getElementById('event-end').value,type:document.getElementById('event-type').value,place:document.getElementById('event-place').value.trim()};state.brandId=document.getElementById('basic-brand').value;}
function submitBasics(e){e.preventDefault();storeBasics();if(!state.basic.name||!state.basic.start||!state.basic.end)return toast('행사명과 운영 기간을 입력해주세요.');if(state.basic.end<state.basic.start){const error=document.getElementById('basic-error');error.hidden=false;error.textContent='종료일은 시작일 이후로 선택해주세요.';return}state.eventName=state.basic.name;state.creationCustom=true;state.generated=false;state.applied=false;state.consent=false;state.approved=false;state.paid=false;state.published=false;state.ended=false;state.createPrompt=`${state.basic.name}. ${state.basic.type}${state.basic.place?' · '+state.basic.place:''}. ${state.basic.start}부터 ${state.basic.end}까지 운영할 게임 이벤트를 만들어줘.`;go('templates')}
const previousTemplates=templates;templates=function(){const h=previousTemplates();if(!state.eventName)return h;const context=`<div class="create-event-summary"><div><strong>${esc(state.eventName)}</strong><span>${esc(state.basic.start)} — ${esc(state.basic.end)}</span></div><a class="text-link" href="#event-basic">기본 정보 수정</a></div>`;return h.replace('<section class="create-hero">',context+'<section class="create-hero">')};
const previousSteps=steps;steps=function(active){let h=previousSteps(active);const b=currentBrand();h=h.replace(badge(),`<select class="event-brand-select" id="event-brand-select" aria-label="현재 행사 브랜드">${brandOptions()}</select>`);if(state.eventName)h=h.replace('루미에르 성수 팝업 룰렛',esc(state.eventName));return h};
const flowEditor=editor;editor=function(p){let h=flowEditor(p);if(state.eventName){const b=currentBrand(),t=currentTemplate();h=h.replaceAll(`${esc(b.short)} ${esc(t.type)} 이벤트`,esc(state.eventName));h=h.replace('<div class="editor-grid">',`<div class="event-basic-summary"><span>운영 기간 ${esc(state.basic.start||'시연 일정')} — ${esc(state.basic.end||'')}</span><a href="#event-basic" class="text-link">기본 정보 수정</a></div><div class="editor-grid">`);}return h};
brandRows=function(b,sending){return `<div class="table-wrap"><table><thead><tr><th>행사명</th><th>상태</th><th>${sending?'발송 건수':'기간'}</th>${sending?'':'<th></th>'}</tr></thead><tbody>${b.list.length?b.list.map((v,i)=>`<tr ${sending?'':`class="clickable event-navigation-row" tabindex="0" data-open-event="${esc(v[0])}" data-event-brand="${b.id}" data-event-status="${v[1]}" aria-label="${esc(v[0])} 행사 열기"`}><td><strong>${esc(v[0])}</strong></td><td>${pill(v[1],v[1]==='검토 중'?'review':v[1]==='시작 예정'?'scheduled':v[1]==='종료'?'ended':'')}</td><td class="dim">${sending?v[2]:b.id==='lumiere'?(i?'09.21 — 09.23':'10.12 — 10.16'):b.id==='novahome'?'10.20 — 10.22':'10.24 — 10.25'}</td>${sending?'':'<td class="row-arrow">→</td>'}</tr>`).join(''):`<tr><td colspan="4" class="dim" style="text-align:center;padding:38px">아직 행사가 없습니다. 새 행사를 만들어보세요.</td></tr>`}</tbody></table></div>`};
eventTable=function(){return `<div class="table-wrap"><table><thead><tr><th>행사</th><th>상태</th><th>현재 작업</th><th>기간</th><th></th></tr></thead><tbody>${eventData.filter(e=>(state.filter==='전체'||e[2]===state.filter)&&(state.brandFilter==='전체'||brands.find(b=>b.id===state.brandFilter)?.short===e[1])).map(e=>{const b=brands.find(b=>b.short===e[1]);return `<tr class="clickable event-navigation-row" tabindex="0" data-open-event="${e[0]}" data-event-brand="${b.id}" data-event-status="${e[2]}" aria-label="${e[0]} 행사 열기"><td><div class="event-cell"><div class="event-icon">${b.initial}</div><div><div class="event-name">${e[0]}</div>${badge(e[1],e[6])}</div></div></td><td>${pill(e[2],e[2]==='검토 중'?'review':e[2]==='시작 예정'?'scheduled':e[2]==='종료'?'ended':'')}</td><td class="dim">${e[3]}</td><td class="dim">${e[4]}</td><td class="row-arrow">→</td></tr>`}).join('')}</tbody></table></div>`};
const flowEvents=events;events=function(){return flowEvents().replace('<div class="filters">',`<div class="filters"><select id="event-brand-filter" class="event-brand-filter" aria-label="행사 브랜드 필터">${brandOptions(true)}</select>`)};
const flowHome=home;home=function(){return flowHome().replace('<div class="filters">',`<div class="filters"><select id="event-brand-filter" class="event-brand-filter" aria-label="행사 브랜드 필터">${brandOptions(true)}</select>`)};
function openWorkspaceEvent(n){state.brandId=n.dataset.eventBrand;state.eventName=n.dataset.openEvent;const status=n.dataset.eventStatus;state.ended=status==='종료';state.published=status==='진행 중'||state.ended;state.approved=state.published||status==='시작 예정';state.creationCustom=true;state.selectedTemplate=/스크래치/.test(state.eventName)?'nova-scratch':/퀴즈/.test(state.eventName)?'green-quiz':'lumiere-wheel';state.basic.name=state.eventName;state.basic.start='';state.basic.end='';go(status==='종료'?'report':status==='검토 중'?'review':status==='시작 예정'?'publish':'operate')}
const flowBind=bind;bind=function(){flowBind();const form=document.getElementById('basic-form');if(form){form.onsubmit=submitBasics;form.querySelectorAll('input,select').forEach(n=>n.onchange=storeBasics)}app.querySelectorAll('[data-open-event]').forEach(n=>{n.onclick=()=>openWorkspaceEvent(n);n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openWorkspaceEvent(n)}}});const sel=document.getElementById('event-brand-select');if(sel)sel.onchange=()=>{enterBrandWorkspace(sel.value)};const filter=document.getElementById('event-brand-filter');if(filter)filter.onchange=()=>{state.brandFilter=filter.value;render()}};
const flowAction=action;action=function(a,n){if(a==='new'){state.basic={name:'',start:'',end:'',type:'팝업스토어',place:''};state.eventName='';go('event-basic');return}flowAction(a,n)};const flowCreateAction=createAction;createAction=function(a){if(a==='brand-create'){state.basic={name:'',start:'',end:'',type:'팝업스토어',place:''};state.eventName='';go('event-basic');return}flowCreateAction(a)};
screens.splice(1,0,['event-basic','C-NEW','행사 기본 정보']);const flowRender=render;render=function(){if(route()==='event-basic'){app.innerHTML=basicInfo();document.body.dataset.screen='event-basic';document.title='행사 기본 정보 · 두잇킷';bind()}else flowRender()};render();
